package com.healthcare.portal.controller;
import com.healthcare.portal.dto.*; import com.healthcare.portal.entity.*; import com.healthcare.portal.exception.ResourceNotFoundException; import com.healthcare.portal.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/medical-records") public class MedicalRecordController { private final MedicalRecordRepository records; private final UserRepository users; private final DoctorProfileRepository doctors; private final AppointmentRepository appointments; public MedicalRecordController(MedicalRecordRepository r,UserRepository u,DoctorProfileRepository d,AppointmentRepository a){records=r;users=u;doctors=d;appointments=a;}
 @GetMapping("/patient/{id}") @PreAuthorize("hasAuthority('ROLE_ADMIN') || hasAuthority('ROLE_DOCTOR') || authentication.principal.id == #id") public List<MedicalRecordResponse> patient(@PathVariable Long id){return records.findByPatientIdOrderByCreatedAtDesc(id).stream().map(MedicalRecordResponse::from).toList();}
 @PostMapping @PreAuthorize("hasAuthority('ROLE_DOCTOR') || hasAuthority('ROLE_ADMIN')") public MedicalRecordResponse create(@RequestBody RecordRequest r){User p=users.findById(r.getPatientId()).orElseThrow(()->new ResourceNotFoundException("Patient not found")); DoctorProfile d=doctors.findById(r.getDoctorId()).orElseThrow(()->new ResourceNotFoundException("Doctor not found")); Appointment a=r.getAppointmentId()==null?null:appointments.findById(r.getAppointmentId()).orElse(null); return MedicalRecordResponse.from(records.save(new MedicalRecord(p,d,a,r.getDiagnosis(),r.getNotes(),r.getDocumentUrl())));}
}
